import numpy as np
from PIL import Image, ImageDraw
cams={
'ego':([[-.000223,1,.000093,.000242],[.706082,.000223,-.70813,-.350993],[-.70813,-.000093,-.706082,1.768277]],[[989.549,0,432],[0,989.549,240],[0,0,1]]),
'shoulder':([[-.615025,-.788507,-.000392,.480459],[-.477177,.372587,-.795915,.336788],[.627731,-.489321,-.605408,.647096]],[[500,0,640],[0,500,360],[0,0,1]])}
for name,(EE,KK) in cams.items():
 im=Image.open('/app/runs/initial/'+('egocentric_mirrored_camera' if name=='ego' else 'over_shoulder_left_camera')+'.png').convert('RGB');d=ImageDraw.Draw(im);E=np.array(EE); K=np.array(KK); R=E[:,:3];t=E[:,3]
 def pix(x,y,z=.003):
  p=R@np.array([x,y,z])+t
  q=K@p
  return (int(round(q[0]/q[2])),int(round(q[1]/q[2])))
 for x in np.arange(.2,1.01,.1):
  pts=[pix(x,y) for y in np.arange(-.55,.551,.01)]
  d.line(pts,fill=(255,0,0),width=1)
  u,v=pix(x,-.55);d.text((u,v),f'x{x:.1f}',fill='yellow')
 for y in np.arange(-.5,.51,.1):
  pts=[pix(x,y) for x in np.arange(.2,1.001,.01)]
  d.line(pts,fill=(0,100,255),width=1)
  u,v=pix(.2,y);d.text((u,v),f'y{y:.1f}',fill='cyan')
 im.save(f'/app/runs/initial/{name}_grid.png')
PY

